/// <summary>
/// init custom fields
/// </summary>
/// <param name = "_basePriceType"></param>
/// <param name = "_itemBasePriceCalcTableTmp"></param>
/// <param name = "_itemBasePriceCalcTransLocal"></param>
/// <param name = "_unitOfMeasure"></param>
/// <returns>GUPItemBasePrice</returns>
public GUPItemBasePrice setItemBasePrice(
    GUPBasePriceType _basePriceType,
    GUPItemBasePriceCalcTable _itemBasePriceCalcTableTmp,
    GUPItemBasePriceCalcTrans _itemBasePriceCalcTransLocal,
    UnitOfMeasureSymbol _unitOfMeasure)
{
    GUPItemBasePrice    itemBasePrice;
    itemBasePrice = next setItemBasePrice(_basePriceType, _itemBasePriceCalcTableTmp, _itemBasePriceCalcTransLocal, _unitOfMeasure);

    itemBasePrice.METVendClaimEnabled = _itemBasePriceCalcTransLocal.METVendClaimEnabled;

    return itemBasePrice;
}

/// <summary>
/// init custom fields
/// </summary>
/// <param name = "_basePriceType"></param>
/// <param name = "_itemBasePriceCalcTableTmp"></param>
/// <param name = "_itemBasePriceCalcTransLocal"></param>
/// <param name = "_unitOfMeasure"></param>
/// <returns>GUPItemBasePriceDelta</returns>
public GUPItemBasePriceDelta setItemBasePriceDelta(
    GUPBasePriceType _basePriceType,
    GUPItemBasePriceCalcTable _itemBasePriceCalcTableTmp,
    GUPItemBasePriceCalcTrans _itemBasePriceCalcTransLocal,
    UnitOfMeasureSymbol _unitOfMeasure)
{
    GUPItemBasePriceDelta itemBasePriceDelta;
    itemBasePriceDelta = next setItemBasePriceDelta(_basePriceType, _itemBasePriceCalcTableTmp, _itemBasePriceCalcTransLocal, _unitOfMeasure);

    itemBasePriceDelta.METVendClaimEnabled = _itemBasePriceCalcTransLocal.METVendClaimEnabled;

    return itemBasePriceDelta;
}
